        while stack:
            r, c = stack.pop()
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if (0 <= nr < h and 0 <= nc < w and
                        (nr, nc) not in seen and out[nr][nc] == 6):
                    seen.add((nr, nc))
                    stack.append((nr, nc))
        for r, c in seen:
            out[r][c] = 0

    return out
